final class Oxygen_AC_Automation {
 const OPT='oxygen_ac_automation_settings'; const CRON='oxygen_ac_daily_job'; private static $instance=null;
 public static function instance(){if(self::$instance===null)self::$instance=new self();return self::$instance;}
 private function __construct(){add_shortcode('oxygen_ac_home',[$this,'home_shortcode']);add_action('template_redirect',[$this,'serve_home_page']);add_shortcode('oxygen_ac_articles',[$this,'articles_shortcode']);add_action('admin_menu',[$this,'admin_menu']);add_action('admin_post_oxygen_ac_save',[$this,'save_settings']);add_action('admin_post_oxygen_ac_run_now',[$this,'run_now']);add_action(self::CRON,[$this,'daily_job']);}
 public static function activate(){if(!wp_next_scheduled(self::CRON)){ $first=strtotime('tomorrow 03:17');wp_schedule_event($first?:time()+HOUR_IN_SECONDS,'daily',self::CRON);} $d=['new_per_day'=>20,'refresh_per_day'=>20,'auto_publish'=>1,'city'=>'مكة المكرمة','keywords'=>"صيانة مكيفات\nغسيل مكيفات\nتنظيف مكيفات\nتركيب مكيفات\nفك ونقل وتركيب مكيف\nصيانة مكيفات سبليت\nصيانة مكيفات مركزية\nغسيل مكيفات شباك\nصيانة داكت وكونسيلد\nشحن فريون المكيف",'openai_key'=>'','openai_model'=>'gpt-4o-mini','refresh_after_days'=>30,'last_run'=>'','last_result'=>''];if(!get_option(self::OPT))add_option(self::OPT,$d,'',false);self::create_pages();}
 public static function deactivate(){wp_clear_scheduled_hook(self::CRON);}
 private static function create_pages(){foreach([['title'=>'أكسجين للصيانة والتبريد','slug'=>'oxygen-ac-home','content'=>'[oxygen_ac_home]'],['title'=>'مقالات أكسجين لصيانة المكيفات','slug'=>'oxygen-ac-articles','content'=>'[oxygen_ac_articles]']] as $p){if(!get_page_by_path($p['slug'],OBJECT,'page'))wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>$p['title'],'post_name'=>$p['slug'],'post_content'=>$p['content']]);}}
 private function settings(){return wp_parse_args((array)get_option(self::OPT,[]),['new_per_day'=>20,'refresh_per_day'=>20,'auto_publish'=>1,'city'=>'مكة المكرمة','keywords'=>"صيانة مكيفات\nغسيل مكيفات\nتركيب مكيفات",'openai_key'=>'','openai_model'=>'gpt-4o-mini','refresh_after_days'=>30,'last_run'=>'','last_result'=>'']);}
 private function get_home_html(){ $file=plugin_dir_path(__FILE__).'assets/oxygen-maintenance-home.html';if(is_readable($file))$html=file_get_contents($file);else{ $parts=glob(plugin_dir_path(__FILE__).'assets/page-part-*.txt');sort($parts);$encoded='';foreach($parts as $part)$encoded.=trim((string)file_get_contents($part));$html=$encoded?gzdecode(base64_decode($encoded)):'';}if(!$html)return ''; $html=preg_replace('/const\s+ADMIN_PASS\s*=\s*["\'][^"\']*["\']\s*;/','const ADMIN_PASS = "";',$html);$html=preg_replace('/function openAdminGate\(\)\s*\{[\s\S]*?\n\s*\}/','function openAdminGate() { showToast("إعدادات النشر الدائمة متاحة من لوحة ووردبريس عبر قائمة ناشر أكسجين."); }',$html,1);$html=preg_replace('/banks:\s*\[[\s\S]*?\n\s*\]/','banks: []',$html,1);$html=preg_replace('/SA\d{18,24}/','',$html);$html=str_replace('علي طلعت محمد زيدان','',$html);return $html;}
 public function home_shortcode(){return $this->get_home_html();}
 public function serve_home_page(){if(!is_page('oxygen-ac-home'))return;$html=$this->get_home_html();if(!$html)return;nocache_headers();header('Content-Type: text/html; charset='.get_bloginfo('charset'));echo $html;exit;}
 public function articles_shortcode(){ $posts=get_posts(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>30,'meta_key'=>'_oxygen_ac_managed','meta_value'=>'1','orderby'=>'date','order'=>'DESC']);ob_start(); ?>
 <div dir="rtl" style="max-width:980px;margin:24px auto;padding:18px;font-family:Tahoma,Arial,sans-serif;line-height:1.9;color:#0f172a"><h1 style="color:#0369a1">مقالات أكسجين لصيانة وغسيل وتركيب المكيفات</h1><p>إرشادات عملية للعناية بالمكيفات في مكة المكرمة وجدة.</p><?php if($posts):foreach($posts as $p):?><article style="padding:16px 0;border-bottom:1px solid #dbeafe"><h2><a style="color:#075985;text-decoration:none" href="<?php echo esc_url(get_permalink($p));?>"><?php echo esc_html(get_the_title($p));?></a></h2><p><?php echo esc_html(get_the_excerpt($p));?></p></article><?php endforeach;else:?><p>ستظهر المقالات هنا بعد أول تشغيل لناشر أكسجين.</p><?php endif;?></div><?php return ob_get_clean();}
 public function admin_menu(){add_menu_page('ناشر أكسجين','ناشر أكسجين','manage_options','oxygen-ac-automation',[$this,'settings_page'],'dashicons-edit-page',58);}
 public function settings_page(){if(!current_user_can('manage_options'))return;$s=$this->settings();$notice=isset($_GET['oxygen_message'])?sanitize_text_field(wp_unslash($_GET['oxygen_message'])):'';?>
 <div class="wrap" dir="rtl" style="max-width:1050px"><h1>ناشر أكسجين للمقالات وSEO</h1><p>يعمل الناشر يوميًا عبر WP-Cron. ينشئ مقالات جديدة ويضيف محتوى مفيدًا للمقالات القديمة المؤهلة بدل نسخ النص القديم كما هو.</p><?php if($notice):?><div class="notice notice-info is-dismissible"><p><?php echo esc_html($notice);?></p></div><?php endif;?><div class="notice notice-warning"><p><strong>تنبيه جودة SEO:</strong> نشر عدد كبير من المقالات المتشابهة قد يضر الجودة والفهرسة. راجع دقة المعلومات وخدماتك الفعلية قبل الاعتماد عليها.</p></div>
 <form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="oxygen_ac_save"><?php wp_nonce_field('oxygen_ac_save');?><table class="form-table"><tr><th><label for="new_per_day">مقالات جديدة يوميًا</label></th><td><input id="new_per_day" name="new_per_day" type="number" min="1" max="20" value="<?php echo esc_attr($s['new_per_day']);?>" required> من 1 إلى 20</td></tr><tr><th><label for="refresh_per_day">مقالات قديمة لتحديثها يوميًا</label></th><td><input id="refresh_per_day" name="refresh_per_day" type="number" min="1" max="20" value="<?php echo esc_attr($s['refresh_per_day']);?>" required> من 1 إلى 20</td></tr><tr><th>حالة النشر</th><td><label><input type="checkbox" name="auto_publish" value="1" <?php checked((int)$s['auto_publish'],1);?>> نشر تلقائي (إلغاء التحديد يجعل الجديد مسودات)</label></td></tr><tr><th><label for="city">المدينة</label></th><td><select id="city" name="city"><?php foreach(['مكة المكرمة','جدة','مكة المكرمة وجدة'] as $city):?><option value="<?php echo esc_attr($city);?>" <?php selected($s['city'],$city);?>><?php echo esc_html($city);?></option><?php endforeach;?></select></td></tr><tr><th><label for="keywords">الكلمات المفتاحية (كل كلمة في سطر)</label></th><td><textarea id="keywords" name="keywords" rows="9" class="large-text code"><?php echo esc_textarea($s['keywords']);?></textarea></td></tr><tr><th><label for="refresh_after_days">الفاصل قبل تحديث المقال مجددًا</label></th><td><input id="refresh_after_days" name="refresh_after_days" type="number" min="7" max="180" value="<?php echo esc_attr($s['refresh_after_days']);?>"> يومًا</td></tr><tr><th><label for="openai_model">نموذج OpenAI (اختياري)</label></th><td><input id="openai_model" name="openai_model" type="text" value="<?php echo esc_attr($s['openai_model']);?>" class="regular-text"><p>بدون مفتاح يستخدم النظام قوالب عربية داخلية.</p></td></tr><tr><th><label for="openai_key">مفتاح OpenAI API (اختياري)</label></th><td><input id="openai_key" name="openai_key" type="password" value="<?php echo esc_attr($s['openai_key']);?>" autocomplete="new-password" class="regular-text"><p>قد تترتب تكلفة استخدام خارجية؛ لا يُعرض المفتاح للزوار.</p></td></tr></table><?php submit_button('حفظ إعدادات الناشر');?></form><hr><h2>تشغيل يدوي</h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="oxygen_ac_run_now"><?php wp_nonce_field('oxygen_ac_run_now');?><?php submit_button('شغّل الناشر الآن','secondary');?></form><h2>نتيجة آخر تشغيل</h2><p><?php echo esc_html($s['last_run']?:'لم يعمل بعد');?></p><pre style="white-space:pre-wrap;background:#fff;padding:12px;border:1px solid #ccd0d4"><?php echo esc_html($s['last_result']?:'لا توجد نتائج بعد.');?></pre><p><a target="_blank" rel="noopener" href="<?php echo esc_url(home_url('/oxygen-ac-home/'));?>">واجهة أكسجين</a> · <a target="_blank" rel="noopener" href="<?php echo esc_url(home_url('/oxygen-ac-articles/'));?>">صفحة المقالات</a></p><h2>استضافة Hostinger</h2><p>للتشغيل حتى عند قلة الزيارات، اضبط Cron يستدعي <code><?php echo esc_html(site_url('/wp-cron.php?doing_wp_cron=1'));?></code> دوريًا إذا كانت الخطة تسمح.</p></div><?php }
 public function save_settings(){if(!current_user_can('manage_options'))wp_die('غير مصرح.');check_admin_referer('oxygen_ac_save');$old=$this->settings();$s=array_merge($old,['new_per_day'=>max(1,min(20,absint($_POST['new_per_day']??20))),'refresh_per_day'=>max(1,min(20,absint($_POST['refresh_per_day']??20))),'auto_publish'=>isset($_POST['auto_publish'])?1:0,'city'=>sanitize_text_field(wp_unslash($_POST['city']??'مكة المكرمة')),'keywords'=>sanitize_textarea_field(wp_unslash($_POST['keywords']??'')),'openai_key'=>trim(sanitize_text_field(wp_unslash($_POST['openai_key']??$old['openai_key']))),'openai_model'=>sanitize_text_field(wp_unslash($_POST['openai_model']??'gpt-4o-mini'))?:'gpt-4o-mini','refresh_after_days'=>max(7,min(180,absint($_POST['refresh_after_days']??30)))]);update_option(self::OPT,$s,false);wp_safe_redirect(add_query_arg('oxygen_message',rawurlencode('تم حفظ الإعدادات.'),admin_url('admin.php?page=oxygen-ac-automation')));exit;}
 public function run_now(){if(!current_user_can('manage_options'))wp_die('غير مصرح.');check_admin_referer('oxygen_ac_run_now');$this->daily_job();wp_safe_redirect(add_query_arg('oxygen_message',rawurlencode('اكتمل التشغيل؛ راجع النتائج أسفل لوحة الناشر.'),admin_url('admin.php?page=oxygen-ac-automation')));exit;}
 public function daily_job(){$s=$this->settings();$today=current_time('Y-m-d');$created=$this->create_new_articles((int)$s['new_per_day'],$s);$updated=$this->refresh_old_articles((int)$s['refresh_per_day'],$s,$today);$s['last_run']=current_time('mysql');$s['last_result']=sprintf("مقالات جديدة: %d\nمقالات قديمة تم تحديثها: %d\nالحد اليومي: %d جديد + %d تحديث\nقد يقل العدد إذا لم توجد مقالات مؤهلة أو عناوين فريدة.",$created,$updated,(int)$s['new_per_day'],(int)$s['refresh_per_day']);update_option(self::OPT,$s,false);}
 private function keywords($s){$rows=preg_split('/[\r\n,،]+/u',(string)$s['keywords']);$rows=array_values(array_unique(array_filter(array_map('trim',$rows))));return $rows?:['صيانة مكيفات','غسيل مكيفات','تركيب مكيفات','تنظيف مكيفات'];}
 private function topic_pool(){return [['name'=>'صيانة المكيفات','key'=>'صيانة مكيفات','sections'=>['علامات احتياج المكيف للصيانة','فحص الفلاتر ومجرى الهواء','متى تحتاج إلى فني مختص']],['name'=>'غسيل المكيفات','key'=>'غسيل مكيفات','sections'=>['الفرق بين التنظيف السطحي والغسيل','حماية الأجزاء الكهربائية أثناء التنظيف','متى يتكرر تنظيف المكيف']],['name'=>'تركيب المكيفات','key'=>'تركيب مكيفات','sections'=>['اختيار موقع الوحدة الداخلية','تجهيز تصريف المياه والتوصيلات','اختبار التشغيل بعد التركيب']],['name'=>'تنظيف فلاتر المكيف','key'=>'تنظيف مكيفات','sections'=>['خطوات العناية بالفلاتر','أخطاء تقلل تدفق الهواء','علامات تستدعي تنظيف الوحدة']],['name'=>'صيانة مكيف سبليت','key'=>'صيانة مكيفات سبليت','sections'=>['فحص الوحدة الداخلية والخارجية','أسباب ضعف التبريد المحتملة','فحوصات قبل طلب الصيانة']],['name'=>'المكيفات المركزية والداكت','key'=>'صيانة مكيفات مركزية','sections'=>['فحص مجاري الهواء','متابعة الترموستات والتحكم','تنظيم الصيانة الوقائية']],['name'=>'فك ونقل وتركيب المكيف','key'=>'فك ونقل وتركيب مكيف','sections'=>['التجهيز قبل الفك','حماية المواسير والوحدات أثناء النقل','اختبار التسريب والتشغيل']],['name'=>'فحص التبريد والفريون','key'=>'فحص فريون المكيف','sections'=>['لماذا لا يكفي التخمين بشأن الفريون','فحص التسريب قبل الشحن','متى يلزم استدعاء فني']]];}
 private function create_new_articles($limit,$s){$created=0;$topics=$this->topic_pool();$keys=$this->keywords($s);$cities=$s['city']==='مكة المكرمة وجدة'?['مكة المكرمة','جدة']:[$s['city']];$seed=(int)current_time('z')+((int)current_time('Y')*367);$attempts=0;$max=max(60,$limit*8);while($created<$limit&&$attempts<$max){$n=$seed+$attempts++;$topic=$topics[$n%count($topics)];$key=$keys[$n%count($keys)];$city=$cities[$n%count($cities)];$opts=[$topic['name'].' في '.$city.': دليل عملي للعناية بالمكيف',$key.' في '.$city.' وأهم خطوات الفحص والتنظيف','متى تحتاج إلى '.$topic['name'].'؟ نصائح لأصحاب المنازل في '.$city,'دليل '.$key.' واختيار وقت الصيانة المناسب في '.$city,$topic['name'].' في '.$city.' مع نصائح لتجنب الأعطال المتكررة'];$title=$opts[intdiv($n,count($topics))%count($opts)];if(get_page_by_title($title,OBJECT,'post'))continue;$content=$this->openai_article($title,$topic,$key,$city,$s);if(!$content)$content=$this->article_html($title,$topic,$key,$city,$n);$status=!empty($s['auto_publish'])?'publish':'draft';$cat=term_exists('صيانة المكيفات','category');if(!$cat)$cat=wp_insert_term('صيانة المكيفات','category',['slug'=>'air-conditioner-maintenance']);$cat_id=is_array($cat)?(int)$cat['term_id']:(int)$cat;$id=wp_insert_post(['post_type'=>'post','post_status'=>$status,'post_title'=>$title,'post_content'=>$content,'post_excerpt'=>wp_trim_words(wp_strip_all_tags($content),28,'…'),'post_category'=>$cat_id?[$cat_id]:[],'meta_input'=>['_oxygen_ac_managed'=>'1','_oxygen_ac_focus_keyword'=>$key,'_oxygen_ac_created_on'=>current_time('mysql')]],true);if(is_wp_error($id)||!$id)continue;$desc=wp_trim_words(wp_strip_all_tags($content),24,'…');update_post_meta($id,'_yoast_wpseo_metadesc',$desc);update_post_meta($id,'rank_math_description',$desc);update_post_meta($id,'_yoast_wpseo_focuskw',$key);update_post_meta($id,'rank_math_focus_keyword',$key);$created++;}return $created;}
 private function openai_article($title,$topic,$keyword,$city,$s){$key=trim((string)($s['openai_key']??''));if($key==='')return '';$model=sanitize_text_field($s['openai_model']??'gpt-4o-mini');$prompt="اكتب مقالًا عربيًا أصيلًا لا يقل عن 250 كلمة عن {$keyword} في {$city}. العنوان: {$title}. المجال: {$topic['name']}. اكتب HTML فقط بمقدمة عملية وعناوين H2 مرقمة 1،2،3 وعناوين H3 مرقمة 1.1 وهكذا، ونصائح وخاتمة وأسئلة شائعة. استخدم الكلمة المفتاحية طبيعيًا دون حشو. لا تخترع أسعارًا أو ضمانات أو ادعاءات محلية. فحص الكهرباء والفريون من اختصاص فني مؤهل. لا تستخدم H1 أو روابط خارجية أو Markdown.";$r=wp_remote_post('https://api.openai.com/v1/chat/completions',['timeout'=>25,'headers'=>['Authorization'=>'Bearer '.$key,'Content-Type'=>'application/json'],'body'=>wp_json_encode(['model'=>$model,'messages'=>[['role'=>'system','content'=>'أنت محرر محتوى عربي متخصص في صيانة التكييف. اكتب معلومات عملية دقيقة وتجنب حشو الكلمات المفتاحية والتكرار.'],['role'=>'user','content'=>$prompt]],'temperature'=>0.75,'max_tokens'=>1500])]);if(is_wp_error($r)||wp_remote_retrieve_response_code($r)<200||wp_remote_retrieve_response_code($r)>=300)return '';$d=json_decode(wp_remote_retrieve_body($r),true);$text=$d['choices'][0]['message']['content']??'';$word_matches=[];preg_match_all('/\p{L}+/u',wp_strip_all_tags($text),$word_matches);if(!is_string($text)||count($word_matches[0]??[])<150)return '';return wp_kses_post($text);}
 private function article_html($title,$topic,$keyword,$city,$seed){$intro=['تعتمد راحة المنزل وكفاءة استهلاك الطاقة على تدفق هواء مناسب وصيانة تُنفذ في وقتها. يساعد الفحص المنظم على اكتشاف المشكلات مبكرًا، لكنه لا يغني عن تقييم الفني عند وجود عطل كهربائي أو تسريب أو صوت غير معتاد.','قبل طلب الخدمة، دوّن الأعراض التي تلاحظها مثل ضعف التبريد أو نزول الماء أو تكرار توقف الوحدة. هذه الملاحظات تساعد الفني على تضييق احتمالات العطل وتحديد الفحوصات الملائمة دون استبدال قطع سليمة دون داعٍ.','يختلف أسلوب التعامل حسب نوع الجهاز وموقع تركيبه وطبيعة الاستخدام. لذلك من الأفضل اتباع دليل الشركة المصنّعة وفصل الكهرباء قبل أي تنظيف يسمح به دليل المستخدم، وترك الأعمال الفنية الداخلية لمختص مؤهل.'];$checks=['ابدأ بفحص الفلتر وتنظيفه بالطريقة الموضحة في دليل الجهاز، ثم تأكد من عدم وجود ستائر أو أثاث يحجب فتحات الهواء. لا تستخدم مواد كيميائية قوية أو ضغط مياه على الأجزاء الكهربائية، ولا تفتح الدوائر أو تمديدات التبريد بنفسك.','افحص بصريًا المنطقة المحيطة بالوحدة بحثًا عن آثار ماء أو أتربة متراكمة أو تلف ظاهر في العزل. حافظ على خلو المنطقة الخارجية من العوائق مع الالتزام بإجراءات السلامة، ولا تصعد إلى أماكن مرتفعة من دون تجهيز مناسب.','سجّل وقت ظهور المشكلة وهل تحدث عند بداية التشغيل أم بعد فترة. إذا استمرت الأعراض بعد تنظيف الفلتر وإعادة ضبط الإعدادات وفق الدليل، اطلب فحصًا فنيًا بدل تكرار تشغيل الجهاز على نحو قد يزيد المشكلة.'];$advice=['تتضمن الزيارة الفنية الجيدة شرحًا للمشكلة، وبيانًا للفحوصات المقترحة، وتوضيحًا للتكلفة قبل أي إصلاح إضافي. اسأل عن حالة القطعة وسبب تعطلها وما إذا كان الإصلاح أو الاستبدال أنسب، واحتفظ بتفاصيل الخدمة والضمان إن توفر.','تختلف التكلفة بحسب نوع المكيف وعدد الوحدات وسهولة الوصول إليها وحالة القطع المطلوبة. اطلب عرضًا يوضح نطاق العمل وما يشمله السعر، ولا تعتمد سعرًا عامًا قبل معرفة تفاصيل الحالة ومكان الخدمة.','يساعد سجل الصيانة على معرفة تكرار الأعطال وموعد تنظيف الفلاتر والفحص الدوري. في البيوت كثيرة الاستخدام أو المواقع التجارية، قد تحتاج الوحدات إلى مراجعة أكثر انتظامًا حسب ظروف التشغيل وتعليمات الشركة المصنّعة.'];$out='<p>'.esc_html($intro[$seed%count($intro)]).' يتناول هذا الدليل '.esc_html($keyword).' في '.esc_html($city).' بخطوات واضحة تناسب الاستخدام المنزلي وتوضح متى تكون العناية البسيطة كافية ومتى يلزم التواصل مع فني.</p>';$num=1;foreach($topic['sections'] as $i=>$heading){$out.='<h2>'.$num.'. '.esc_html($heading).'</h2><p>'.esc_html($checks[($seed+$i)%count($checks)]).'</p><h3>'.$num.'.1 '.esc_html($i===0?'خطوة عملية يمكن البدء بها':($i===1?'ملاحظات مهمة أثناء الفحص':'متى تطلب المساعدة')).'</h3><p>'.esc_html($advice[($seed+$i+1)%count($advice)]).'</p>';$num++;}$out.='<h2>'.$num.'. أسئلة شائعة حول '.esc_html($keyword).'</h2><h3>'.$num.'.1 هل يمكن تنفيذ كل أعمال الصيانة في المنزل؟</h3><p>يمكن للمستخدم تنظيف الأجزاء التي يسمح بها دليل الجهاز فقط. أما فحص الكهرباء أو فتح دائرة التبريد أو معالجة التسريب فينبغي أن ينفذه فني مؤهل وبالأدوات المناسبة.</p><h3>'.$num.'.2 ما المعلومات التي أجهزها قبل الاتصال؟</h3><p>جهّز نوع المكيف، والعرض الذي تلاحظه، وموقع الوحدة، وموعدًا مناسبًا للزيارة. اطلب شرحًا واضحًا لنطاق العمل والتكلفة المتوقعة قبل بدء الإصلاح.</p><h2>'.($num+1).'. خلاصة الدليل</h2><p>إن متابعة الفلاتر وفتحات الهواء وملاحظة التغييرات في الأداء تساعد على العناية بالمكيف، لكنها لا تضمن زوال كل الأعطال. عند استمرار المشكلة، اجعل التشخيص قائمًا على فحص مناسب بدل التخمين أو إضافة غاز التبريد دون التأكد من السبب. هذه إرشادات عامة، وتعتمد إجراءات السلامة والصيانة النهائية على نوع الجهاز وتعليماته.</p><p><strong>الكلمة المفتاحية:</strong> '.esc_html($keyword).' · <strong>المدينة:</strong> '.esc_html($city).'. تحدد الأسعار والتوافر حسب نوع الوحدة وموقعها وحالة العطل.</p>';return $out;}
 private function refresh_old_articles($limit,$s,$today){$all=get_posts(['post_type'=>'post','post_status'=>'publish','numberposts'=>1000,'orderby'=>'modified','order'=>'ASC']);$eligible=[];$threshold=time()-max(7,(int)$s['refresh_after_days'])*DAY_IN_SECONDS;$pattern='/مكيف|تكييف|تكييفات|غسيل|تنظيف|صيانة|تركيب|تبريد|فريون|سبليت|داكت|كونسيلد|مركزي|هواء/u';foreach($all as $p){if(get_post_meta($p->ID,'_oxygen_ac_refreshed_date',true)===$today)continue;$last=get_post_meta($p->ID,'_oxygen_ac_last_refresh',true);$changed=get_post_modified_time('U',true,$p);if($last&&strtotime($last)>$threshold)continue;if(!$last&&$changed>$threshold&&get_post_meta($p->ID,'_oxygen_ac_managed',true)!=='1')continue;if(!preg_match($pattern,$p->post_title.' '.wp_strip_all_tags($p->post_content)))continue;$eligible[]=$p;}$updated=0;$topics=$this->topic_pool();$keys=$this->keywords($s);foreach(array_slice($eligible,0,$limit) as $i=>$p){$n=(int)current_time('z')+$i+(int)$p->ID;$topic=$topics[$n%count($topics)];$key=$keys[$n%count($keys)];$section='<hr><h2>مراجعة الصيانة: معلومات إضافية بتاريخ '.esc_html(wp_date('j F Y')).'</h2><p>ضمن تحديث هذا المقال، نضيف إرشادات عملية مرتبطة بـ '.esc_html($key).' في '.esc_html($s['city']).'. تحقق من نظافة الفلاتر وحرية حركة الهواء حسب تعليمات الشركة المصنّعة، وراقب وجود أصوات أو روائح أو ماء غير معتاد. افصل الجهاز قبل تنظيف الجزء المسموح للمستخدم الوصول إليه، وتجنب ملامسة الأسلاك أو فتح دائرة التبريد.</p><h3>خطوات الفحص والمتابعة</h3><p>دوّن الأعراض ووقت حدوثها، وتأكد من إعدادات التشغيل ودرجة الحرارة المطلوبة. إذا كان التبريد ضعيفًا باستمرار أو تكرر فصل القاطع أو ظهرت علامات تسريب، أوقف الاستخدام عند وجود خطر واطلب فحصًا فنيًا. لا تضف غاز التبريد عشوائيًا؛ يجب أولًا التحقق من التسريب وسبب المشكلة باستخدام الأدوات المناسبة.</p><h3>ما الذي يجب توضيحه قبل تنفيذ الخدمة؟</h3><p>اطلب توضيح نطاق العمل والقطع المشمولة والسعر المتوقع وأي ضمان متاح قبل الموافقة. تختلف تكلفة '.esc_html($key).' حسب نوع الوحدة وعدد الأجهزة وسهولة الوصول والحالة الفنية؛ لذلك لا تعد الأسعار العامة بديلًا عن المعاينة. يساعد الاحتفاظ بسجل الزيارات على متابعة الحالة واختيار موعد الصيانة القادمة.</p><p><strong>عبارات البحث ذات الصلة:</strong> '.esc_html($key).'، '.esc_html($topic['key']).'، '.esc_html($s['city']).'. تمت إضافة هذه المعلومات دون تغيير عنوان المقال أو رابطه الدائم.</p>';$res=wp_update_post(['ID'=>$p->ID,'post_content'=>rtrim($p->post_content)."\n\n".$section],true);if(!is_wp_error($res)&&$res){update_post_meta($p->ID,'_oxygen_ac_last_refresh',current_time('mysql'));update_post_meta($p->ID,'_oxygen_ac_refreshed_date',$today);update_post_meta($p->ID,'_oxygen_ac_focus_keyword',$key);$desc=wp_trim_words(wp_strip_all_tags($p->post_content.' '.$section),24,'…');update_post_meta($p->ID,'_yoast_wpseo_metadesc',$desc);update_post_meta($p->ID,'rank_math_description',$desc);$updated++;}}return $updated;}
}
register_activation_hook(__FILE__,['Oxygen_AC_Automation','activate']);register_deactivation_hook(__FILE__,['Oxygen_AC_Automation','deactivate']);Oxygen_AC_Automation::instance();
